{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "40면 공영주차장의 가족배려 주차면 최소 면수와 그중 확장형 면수",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "기계식 주차구획을 제외한 총주차대수가 30대 이상이므로 총주차대수의 10% 이상을 가족배려주차장 주차구획으로 설치해야 한다. 40면의 10%는 4면이므로 가족배려 주차면은 최소 4면이다. 확장형 주차구획을 설치하는 주차장이므로 가족배려주차장 주차구획의 50% 이상을 확장형 주차구획으로 해야 하므로, 그중 최소 2면을 확장형으로 해야 한다.",
          "b_ids": "주차장:제25조의2제1항, 주차장:제25조의2제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
